    66	static inline int
    67	scratch_attr_too_big (struct _internal_exr_seq_scratch* scr, int32_t attrsz)
    68	{
    69	    int64_t acmp = (int64_t) attrsz;
    70	    if (scr->ctxt->file_size > 0 && (acmp > scr->navail))
    71	    {
    72	        int64_t test = acmp - scr->navail;
    73	        int64_t foff = (int64_t) scr->fileoff;
    74	        if ((foff + test) > scr->ctxt->file_size) return 1;
    75	    }
    76	    return 0;
    77	}
