    79	#define SCRATCH_BUFFER_SIZE 4096
    80	
    81	static exr_result_t
    82	scratch_seq_read (struct _internal_exr_seq_scratch* scr, void* buf, uint64_t sz)
    83	{
    84	    uint8_t*     outbuf  = buf;
    85	    uint64_t     nCopied = 0;
    86	    uint64_t     notdone = sz;
    87	    exr_result_t rv      = -1;
    88	
    89	    while (notdone > 0)
    90	    {
    91	        if (scr->navail > 0)
    92	        {
    93	            uint64_t nLeft = (uint64_t) scr->navail;
    94	            uint64_t nCopy = notdone;
    95	            if (nCopy > nLeft) nCopy = nLeft;
    96	            memcpy (outbuf, scr->scratch + scr->curpos, nCopy);
    97	            scr->curpos += nCopy;
    98	            scr->navail -= (int64_t) nCopy;
    99	            notdone -= nCopy;
   100	            outbuf += nCopy;
   101	            nCopied += nCopy;
   102	        }
   103	        else if (notdone > SCRATCH_BUFFER_SIZE)
   104	        {
   105	            uint64_t nPages  = notdone / SCRATCH_BUFFER_SIZE;
   106	            int64_t  nread   = 0;
   107	            uint64_t nToRead = nPages * SCRATCH_BUFFER_SIZE;
   108	            rv               = scr->ctxt->do_read (
   109	                scr->ctxt,
   110	                outbuf,
   111	                nToRead,
   112	                &(scr->fileoff),
   113	                &nread,
   114	                EXR_MUST_READ_ALL);
   115	            if (nread > 0)
   116	            {
   117	                notdone -= (uint64_t) nread;
   118	                outbuf += nread;
   119	                nCopied += (uint64_t) nread;
   120	            }
   121	            else { break; }
   122	        }
   123	        else
   124	        {
   125	            int64_t nread = 0;
   126	            rv            = scr->ctxt->do_read (
   127	                scr->ctxt,
   128	                scr->scratch,
   129	                SCRATCH_BUFFER_SIZE,
   130	                &(scr->fileoff),
   131	                &nread,
   132	                EXR_ALLOW_SHORT_READ);
   133	            if (nread > 0)
   134	            {
   135	                scr->navail = nread;
   136	                scr->curpos = 0;
   137	            }
   138	            else
   139	            {
   140	                if (nread == 0)
   141	                    rv = scr->ctxt->report_error (
   142	                        scr->ctxt,
   143	                        EXR_ERR_READ_IO,
   144	                        "End of file attempting to read header");
   145	                break;
   146	            }
   147	        }
   148	    }
   149	    if (rv == -1)
   150	    {
   151	        if (nCopied == sz)
   152	            rv = EXR_ERR_SUCCESS;
   153	        else
   154	            rv = EXR_ERR_READ_IO;
   155	    }
   156	    return rv;
   157	}
