   159	static exr_result_t
   160	scratch_seq_skip (struct _internal_exr_seq_scratch* scr, int32_t sz)
   161	{
   162	    uint64_t     nCopied = 0;
   163	    uint64_t     notdone = (uint64_t) sz;
   164	    exr_result_t rv      = -1;
   165	
   166	    while (notdone > 0)
   167	    {
   168	        if (scr->navail > 0)
   169	        {
   170	            uint64_t nLeft = (uint64_t) scr->navail;
   171	            uint64_t nCopy = notdone;
   172	            if (nCopy > nLeft) nCopy = nLeft;
   173	            scr->curpos += nCopy;
   174	            scr->navail -= (int64_t) nCopy;
   175	            notdone -= nCopy;
   176	            nCopied += nCopy;
   177	        }
   178	        else
   179	        {
   180	            int64_t nread = 0;
   181	            rv            = scr->ctxt->do_read (
   182	                scr->ctxt,
   183	                scr->scratch,
   184	                SCRATCH_BUFFER_SIZE,
   185	                &(scr->fileoff),
   186	                &nread,
   187	                EXR_ALLOW_SHORT_READ);
   188	            if (nread > 0)
   189	            {
   190	                scr->navail = nread;
   191	                scr->curpos = 0;
   192	            }
   193	            else
   194	            {
   195	                if (nread == 0)
   196	                    rv = scr->ctxt->report_error (
   197	                        scr->ctxt,
   198	                        EXR_ERR_READ_IO,
   199	                        "End of file attempting to read header");
   200	                break;
   201	            }
   202	        }
   203	    }
   204	    if (rv == -1)
   205	    {
   206	        if (nCopied == (uint64_t) sz)
   207	            rv = EXR_ERR_SUCCESS;
   208	        else
   209	            rv = EXR_ERR_READ_IO;
   210	    }
   211	    return rv;
   212	}
